-- XWayland apps render at native res (see xwayland block); make Steam scale its own UI to match the 1.6 monitor scale
hl.env("STEAM_FORCE_DESKTOPUI_SCALING", "1.6")

-- Hybrid GPU: render on the Intel iGPU (drives eDP), keep NVIDIA as secondary
-- for external outputs. Symlinks come from /etc/udev/rules.d/99-dri-names.rules;
-- only set when they exist so a missing rule can't stop Hyprland starting.
local function exists(path) local f = io.open(path, "r"); if f then f:close() return true end return false end
if exists("/dev/dri/intel-igpu") and exists("/dev/dri/nvidia-dgpu") then
    hl.env("AQ_DRM_DEVICES", "/dev/dri/intel-igpu:/dev/dri/nvidia-dgpu")
end


