hl.bind((mac and "ALT" or mainMod) .. " + SHIFT + grave", hl.dsp.exec_cmd("~/.local/bin/aeris-ask toggle --selection"), { description = "Ask the local model about the selected text" })
hl.bind(mac and "SUPER + CTRL + F" or mainMod .. " + F", hl.dsp.window.fullscreen(), { description = "Full screen (covers bar)" })
hl.bind(mac and "CTRL + ALT + Return" or mainMod .. " + SHIFT + F", hl.dsp.window.fullscreen({ mode = "maximized" }), { description = "Maximize window" })
-- Screenshots & recordings, macOS layout on the Cmd-position key (cmdMod, defined
-- above: Cmd/Super on Apple keyboards and the Razer, left Alt on other PC layouts): Shift+3 whole screen,
-- 4 select area, 5 record area, 6 record whole screen (recordings toggle off on a
-- second press), D annotate. Saved to ~/Pictures/Screenshots /
-- ~/Videos/Screenrecordings; screenshots also go to the clipboard. Move-to-workspace
-- lives on SUPER+ALT+number to make room. The Print binds are aliases for keyboards
-- that have the key (Razer); the T2 Mac has none.
hl.bind(cmdMod .. " + SHIFT + 3",  hl.dsp.exec_cmd("~/.local/bin/screenshot screen"), { description = "Screenshot: whole screen" })
hl.bind(cmdMod .. " + SHIFT + 4",  hl.dsp.exec_cmd("~/.local/bin/screenshot area"), { description = "Screenshot: select area" })
hl.bind(cmdMod .. " + SHIFT + 5",  hl.dsp.exec_cmd("~/.local/bin/screenrecord area"), { description = "Screen recording: area (press again to stop)" })
hl.bind(cmdMod .. " + SHIFT + 6",  hl.dsp.exec_cmd("~/.local/bin/screenrecord screen"), { description = "Screen recording: whole screen (press again to stop)" })
hl.bind(cmdMod .. " + SHIFT + 7",  hl.dsp.exec_cmd("monologue"), { description = "Camera recording (Monologue): Space records, Enter edits" })
hl.bind(cmdMod .. " + SHIFT + D",  hl.dsp.exec_cmd("~/.local/bin/screenshot annotate"), { description = "Screenshot: select area and annotate (draw)" })
hl.bind("Print",                    hl.dsp.exec_cmd("~/.local/bin/screenshot area"), { description = "Screenshot: select area" })
hl.bind("SHIFT + Print",            hl.dsp.exec_cmd("~/.local/bin/screenshot screen"), { description = "Screenshot: whole screen" })
hl.bind("CTRL + Print",             hl.dsp.exec_cmd("~/.local/bin/screenshot annotate"), { description = "Screenshot: select area and annotate" })
hl.bind("ALT + Print",              hl.dsp.exec_cmd("~/.local/bin/screenrecord area"), { description = "Screen recording: area (press again to stop)" })
hl.bind("ALT + SHIFT + Print",      hl.dsp.exec_cmd("~/.local/bin/screenrecord screen"), { description = "Screen recording: whole screen (press again to stop)" })

-- Push-to-talk dictation (voxtype): hold Right Option/Alt (or Right Ctrl on keyboards that
-- have one), speak, release to type the text. non_consuming keeps the key working as a
-- normal modifier in apps. Release fires with the modifier still in the modmask, so each
-- key is bound both with and without it.
hl.bind("Alt_R", hl.dsp.exec_cmd("voxtype record start"), { description = "Dictate: hold, speak, release (voxtype)", non_consuming = true })
hl.bind("Alt_R", hl.dsp.exec_cmd("voxtype record stop"), { description = "Dictate: stop (release)", release = true, non_consuming = true })
hl.bind("ALT + Alt_R", hl.dsp.exec_cmd("voxtype record stop"), { description = "Dictate: stop (release)", release = true, non_consuming = true })
hl.bind("Control_R", hl.dsp.exec_cmd("voxtype record start"), { description = "Dictate: hold, speak, release (voxtype)", non_consuming = true })
hl.bind("Control_R", hl.dsp.exec_cmd("voxtype record stop"), { description = "Dictate: stop (release)", release = true, non_consuming = true })
hl.bind("CTRL + Control_R", hl.dsp.exec_cmd("voxtype record stop"), { description = "Dictate: stop (release)", release = true, non_consuming = true })
hl.bind(wm .. " + P", hl.dsp.window.pseudo(), { description = "Pseudo-tile window" })
hl.bind(wm .. " + J", hl.dsp.layout("togglesplit"), { description = "Flip split: rows / columns" })    -- dwindle only

-- Switch windows like Alt+Tab elsewhere: cycle focus and raise the window
hl.bind("ALT + Tab", hl.dsp.window.cycle_next(), { description = "Next window" })
hl.bind("ALT + Tab", hl.dsp.window.bring_to_top())
hl.bind("ALT + SHIFT + Tab", hl.dsp.window.cycle_next({ next = false }), { description = "Previous window" })
hl.bind("ALT + SHIFT + Tab", hl.dsp.window.bring_to_top())

-- Move focus with the window-management tier (wm: SUPER, or Ctrl+Option on the macOS layout) + arrow keys
hl.bind(wm .. " + left",  hl.dsp.focus({ direction = "left" }), { description = "Focus window left" })
hl.bind(wm .. " + right", hl.dsp.focus({ direction = "right" }), { description = "Focus window right" })
hl.bind(wm .. " + up",    hl.dsp.focus({ direction = "up" }), { description = "Focus window up" })
hl.bind(wm .. " + down",  hl.dsp.focus({ direction = "down" }), { description = "Focus window down" })
hl.bind(wm .. " + SHIFT + left",  hl.dsp.window.move({ direction = "left" }), { description = "Move window left" })
hl.bind(wm .. " + SHIFT + right", hl.dsp.window.move({ direction = "right" }), { description = "Move window right" })
hl.bind(wm .. " + SHIFT + up",    hl.dsp.window.move({ direction = "up" }), { description = "Move window up" })
hl.bind(wm .. " + SHIFT + down",  hl.dsp.window.move({ direction = "down" }), { description = "Move window down" })
hl.bind(mainMod .. " + CTRL + left",  hl.dsp.window.resize({ x = -60, y = 0, relative = true }), { description = "Resize: narrower", repeating = true })
hl.bind(mainMod .. " + CTRL + right", hl.dsp.window.resize({ x = 60, y = 0, relative = true }), { description = "Resize: wider", repeating = true })
hl.bind(mainMod .. " + CTRL + up",    hl.dsp.window.resize({ x = 0, y = -60, relative = true }), { description = "Resize: shorter", repeating = true })
hl.bind(mainMod .. " + CTRL + down",  hl.dsp.window.resize({ x = 0, y = 60, relative = true }), { description = "Resize: taller", repeating = true })
-- Resize the focused window with the Cmd key (left of the spacebar): = wider, - thinner;
-- with Shift, taller / shorter. Replaces app zoom (Cmd+=/-) and the scale stepper's old keys.
-- equal/plus and minus/underscore both bound: with SHIFT held the keysym differs by layout.
hl.bind(cmdMod .. " + equal",              hl.dsp.window.resize({ x = 60, y = 0, relative = true }), { description = "Resize: wider", repeating = true })
hl.bind(cmdMod .. " + minus",              hl.dsp.window.resize({ x = -60, y = 0, relative = true }), { description = "Resize: thinner", repeating = true })
hl.bind(cmdMod .. " + SHIFT + equal",      hl.dsp.window.resize({ x = 0, y = 60, relative = true }), { description = "Resize: taller", repeating = true })
hl.bind(cmdMod .. " + SHIFT + plus",       hl.dsp.window.resize({ x = 0, y = 60, relative = true }), { repeating = true })
hl.bind(cmdMod .. " + SHIFT + minus",      hl.dsp.window.resize({ x = 0, y = -60, relative = true }), { description = "Resize: shorter", repeating = true })
hl.bind(cmdMod .. " + SHIFT + underscore", hl.dsp.window.resize({ x = 0, y = -60, relative = true }), { repeating = true })
-- Display scale stepper (runtime; a config reload returns to the saved scale), moved to SUPER+CTRL.
hl.bind(mainMod .. " + CTRL + equal",       hl.dsp.exec_cmd("~/.local/bin/display-scale up"), { description = "Display scale: larger UI" })
hl.bind(mainMod .. " + CTRL + plus",        hl.dsp.exec_cmd("~/.local/bin/display-scale up"))
hl.bind(mainMod .. " + CTRL + KP_Add",      hl.dsp.exec_cmd("~/.local/bin/display-scale up"))
hl.bind(mainMod .. " + CTRL + minus",       hl.dsp.exec_cmd("~/.local/bin/display-scale down"), { description = "Display scale: more real estate" })
hl.bind(mainMod .. " + CTRL + KP_Subtract", hl.dsp.exec_cmd("~/.local/bin/display-scale down"))

-- Switch workspaces with mainMod + [0-9]
-- Move active window to a workspace with mainMod + SHIFT + [0-9]
for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    -- Move is on ALT (not SHIFT): SUPER+SHIFT+3/4/5/6 are the macOS-style capture keys
    hl.bind((mac and "CTRL + " or mainMod .. " + ") .. key, hl.dsp.focus({ workspace = i}), { description = "Go to workspace " .. i })
    hl.bind(mainMod .. " + ALT + " .. key,       hl.dsp.window.move({ workspace = i }), { description = "Move window to workspace " .. i })
end
if mac then   -- macOS Spaces: Ctrl+left/right steps through workspaces
    hl.bind("CTRL + left",  hl.dsp.focus({ workspace = "e-1" }), { description = "Previous workspace" })
    hl.bind("CTRL + right", hl.dsp.focus({ workspace = "e+1" }), { description = "Next workspace" })
end

-- Example special workspace (scratchpad)
hl.bind(wm .. " + S",         hl.dsp.workspace.toggle_special("magic"), { description = "Toggle scratchpad workspace" })
hl.bind(wm .. " + SHIFT + S", hl.dsp.window.move({ workspace = "special:magic" }), { description = "Move window to scratchpad" })

-- Scroll through existing workspaces with mainMod + scroll
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }), { description = "Next workspace" })
hl.bind(mainMod .. " + mouse_up",   hl.dsp.focus({ workspace = "e-1" }), { description = "Previous workspace" })

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(),   { description = "Move window (drag)", mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { description = "Resize window (drag)", mouse = true })

-- Laptop multimedia keys for volume and LCD brightness
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("swayosd-client --output-volume raise"), { description = "Volume up", locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("swayosd-client --output-volume lower"),      { description = "Volume down", locked = true, repeating = true })
hl.bind("XF86AudioMute",        hl.dsp.exec_cmd("swayosd-client --output-volume mute-toggle"),     { description = "Mute speakers", locked = true, repeating = true })
hl.bind("XF86AudioMicMute",     hl.dsp.exec_cmd("swayosd-client --input-volume mute-toggle"),   { description = "Mute microphone", locked = true, repeating = true })
hl.bind("XF86MonBrightnessUp",  hl.dsp.exec_cmd("swayosd-client --brightness raise"),                  { description = "Brightness up", locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown",hl.dsp.exec_cmd("swayosd-client --brightness lower"),                  { description = "Brightness down", locked = true, repeating = true })

-- Requires playerctl
hl.bind("XF86AudioNext",  hl.dsp.exec_cmd("playerctl next"),       { description = "Next track", locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { description = "Play / pause", locked = true })
hl.bind("XF86AudioPlay",  hl.dsp.exec_cmd("playerctl play-pause"), { description = "Play / pause", locked = true })
hl.bind("XF86AudioPrev",  hl.dsp.exec_cmd("playerctl previous"),   { description = "Previous track", locked = true })


